/** `undefined` when the store lookup failed, so the next call tries again. */
async function resolveStoreCapabilities(mastra) {
	let store;
	try {
		store = await mastra.getStorage()?.getStore("observability");
	} catch {
		return;
	}
	if (!store) return NO_STORE;
	return {
		observability: require_server_handlers_observability_shared.getObservabilityStorageCapabilities(store),
		scores: {
			list: require_server_handlers_observability_shared.implementsObservabilityStorageMethod(store, "listScores"),
			analyze: SCORE_ANALYSIS_METHODS.every((method) => require_server_handlers_observability_shared.implementsObservabilityStorageMethod(store, method))
		},
		traceStructure: require_server_handlers_observability_shared.implementsObservabilityStorageMethod(store, "getTraceLight") || require_server_handlers_observability_shared.implementsObservabilityStorageMethod(store, "getStructure")
	};
}
/**
* Store capabilities are resolved once per Mastra instance (the store does not change while the process runs),
* unless the lookup fails, which is retried on the next call; memory and the editor are checked on every call
* because agents can be added at runtime.
*/
async function getBuiltinMCPCapabilities(mastra) {
	let pending = storeCapabilities.get(mastra);
	if (!pending) {
		pending = resolveStoreCapabilities(mastra);
		storeCapabilities.set(mastra, pending);
	}
	const storage = mastra.getStorage();
	const storedAgents = Boolean(mastra.getEditor?.()) && Boolean(await storage?.getStore("agents").catch(() => void 0));
	const agentMemory = Object.values(mastra.listAgents?.() ?? {}).some((agent) => agent.hasOwnMemory?.());
	const store = await pending;
	if (!store) storeCapabilities.delete(mastra);
	return {
		...store ?? NO_STORE,
		storedAgents,
		memory: agentMemory || storedAgents
	};
}
