async function describeBuiltinMCP(mastra, routePrefix = "") {
	const server = mastra.getServer();
	if (!isBuiltinMCPEnabled(mastra)) return {
		enabled: false,
		disabledReason: server?.mcp?.enabled === false ? "config" : "production-without-auth"
	};
	const config = resolveBuiltinMCPConfig(mastra);
	const auth = server?.auth;
	return {
		enabled: true,
		path: `${routePrefix}${getBuiltinMCPMountedPath(mastra)}`,
		mcpPackageInstalled: await isMCPPackageInstalled(),
		toolsets: await getServedToolsets(mastra, config.toolsets),
		readOnly: config.readOnly,
		auth: auth ? {
			type: "protected",
			provider: "name" in auth && typeof auth.name === "string" && auth.name || null
		} : {
			type: "open",
			devOnly: server?.mcp?.enabled !== true
		}
	};
}
